fn largest_power_of_two_le(n: i8) -> i8 {
    // Start with the largest possible power of 2 that fits in i8
    let mut z: i8 = 64; // 2^6 = 64, which is the largest power of 2 <= 127 (i8::MAX)
    
    // Decrease z until it's <= n
    while z > n {
        z >>= 1; // Divide by 2
    }
    
    z
}

